from pathlib import Path
import hashlib,json,sys
p=Path(sys.argv[1]);raw=p.read_bytes()
assert hashlib.sha256(raw).hexdigest()=='a5625474be608cd836928d6a46a81ca11a57f3cbc827a673a789660588392492','Exact Tab1 base required'
lines=raw.decode('utf-8').splitlines(keepends=True)
ops=json.loads("[{\"start\":16959,\"count\":1,\"lines\":[\"  const rememberReview=(id,reason)=>{job.issues=job.issues||[];if(!job.issues.some(x=>str(x.id)===str(id)))job.issues.push({id:str(id),reason,cloudStatus:'rejected'});job.ids=job.ids.filter(x=>str(x)!==str(id));save(job);};\",\"  const originalOf=row=>row.payload?.r340_original||row.payload;\",\"  const canonical=v=>v&&typeof v==='object'?(Array.isArray(v)?v.map(canonical):Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])]))):v;\",\"  const confirmed=(row,id)=>{const p=originalOf(row),c=job.confirmed?.[id];return !!p&&!!c&&str(p.batch_id)===str(job.batch)&&str(p.barcode)===str(c.barcode)&&int(p.counted_qty)===c.count&&(!c.original||JSON.stringify(canonical(c.original))===JSON.stringify(canonical(p)));};\",\"  const verifiedReview=(row,id)=>row?.status==='rejected'&&confirmed(row,id)&&row.result?.review_protocol==='r346'&&str(row.result.event_id)===str(id)&&str(row.result.batch_id)===str(job.batch)&&row.result.status==='review';\",\"  const exclude=async(id,reason,row)=>{\",\"   if(window.P7Cloud?.url!=='https://jdcolkgzwqpwbfvcrdje.supabase.co')throw Error('R346_wrong_store');\",\"   if(!job.ownerConfirmedCount||!confirmed(row,id))throw Error('R346_review_not_confirmed');\",\"   const durable=JSON.parse(localStorage.getItem(DB)||'null');\",\"   if(!Array.isArray(durable?.products)||!Array.isArray(state?.products)||durable.pos7InventoryApplied?.[id]||state.pos7InventoryApplied?.[id])throw Error('R346_review_local_state_unverified');\",\"   const p=originalOf(row);\",\"   const ack=await window.P7Cloud.rpc('pos7_inventory_mark_review_r346',{p_event_id:id,p_device:device,p_original:p,p_reason:str(reason).slice(0,500)});\",\"   if(ack?.status!=='review'||ack.review_protocol!=='r346'||str(ack.event_id)!==str(id)||str(ack.batch_id)!==str(job.batch))throw Error('R346_review_ack_unverified');\",\"   rememberReview(id,reason);\",\"  };\"]},{\"start\":16962,\"count\":1,\"lines\":[\"   if(!row){const found=await window.P7Cloud.req('/rest/v1/pos7_owner_commands?store_id=eq.pos7&event_id=eq.'+encodeURIComponent(id)+'&select=event_id,status,payload,result&limit=1');if(found?.length===1&&verifiedReview(found[0],id)){rememberReview(id,str(found[0].result.reason||'بحاجة إلى مراجعة'));continue;}throw Error('R346: حالة الطلب غير مؤكدة؛ لن نستبعد طلبًا معتمدًا أو مفقودًا');}\"]},{\"start\":16967,\"count\":1,\"lines\":[\"   if(job.reviewOnly?.includes(str(id))||!isSafe(row,cloud)){await exclude(id,'صنف يحتاج مراجعة الهوية أو المراجعة: '+str(row.payload?.barcode),row);continue;}\"]},{\"start\":16972,\"count\":1,\"lines\":[\"   if(matches.length!==1){await exclude(id,'الباركود غير فريد على السحابة: '+requestBarcode,row);continue;}\"]},{\"start\":16974,\"count\":1,\"lines\":[\"   if(distinctProducts.has(str(matched.id))){await exclude(id,'الصنف مكرر في الدفعة',row);continue;}\"]},{\"start\":16978,\"count\":1,\"lines\":[\"   if(prepared?.status==='review'){await exclude(id,str(prepared.reason||'هوية تحتاج مراجعة'),row);continue;}\"]},{\"start\":16984,\"count\":1,\"lines\":[\"   if(!check?.ok){await exclude(id,'تعارض في بيانات التاب: '+str(check?.reason),row);continue;}\"]},{\"start\":16986,\"count\":1,\"lines\":[\"   if(anchor&&anchor.localId!==str(window.POS7_R340_guard.localId)){await exclude(id,'هوية الصنف المحلية تغيرت',row);continue;}\"]},{\"start\":17093,\"count\":1,\"lines\":[\"   const btn=document.createElement('button');btn.textContent='✅ اعتماد '+safe.length+' وإبلاغ الهاتف بمراجعة '+(rs.length-safe.length)+' صنف';btn.disabled=!rs.length;\"]},{\"start\":17099,\"count\":1,\"lines\":[\"    const ids=rs.map(x=>str(x.event_id));\"]},{\"start\":17102,\"count\":1,\"lines\":[\"    if(!confirm('R342: أؤكد أن الكميات المجرودة تمثل العدد الفعلي المطلوب اعتماده الآن، مع إدخال أي بيع أو مرتجع حدث بعد العد في الحسبان. ستُسجل فروق مخزون التاب في سجل تسوية، ويُفحص مخزون السحابة قبل كل صنف. الأصناف غير المطابقة ستُرسل للهاتف بحالة بحاجة إلى مراجعة دون تغيير المخزون. هل تعتمد الدفعة؟'))return;\"]},{\"start\":17106,\"count\":1,\"lines\":[\"     save({version:343,batch,ids,anchors,reviewOnly:rs.filter(r=>!safe.includes(r)).map(r=>str(r.event_id)),confirmed:Object.fromEntries(rs.map(r=>[str(r.event_id),{barcode:str(r.payload.r340_original?.barcode??r.payload.barcode),count:int(r.payload.counted_qty),original:r.payload.r340_original||r.payload}])),approved:[],issues:[],state:'running',ownerConfirmedCount:true});resume();\"]}]")
for op in reversed(ops):
    i=op['start'];lines[i:i+op['count']]=[x+'\n' for x in op['lines']]
out=''.join(lines).encode('utf-8')
assert hashlib.sha256(out).hexdigest()=='196d3ce42f16b772c41e6b86b7c95be46bdc7a915e06b149db4aee9301b3e11c','Exact R346 review source mismatch'
p.write_bytes(out)
print('Tab1 exact R346 review source verified')
